77	    /**
78	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
79	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
80	     */
81	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
