83	    /**
84	     * Domains known to hand out disposable/throwaway mailboxes. An owner whose email domain is on
85	     * this blocklist is rejected: such addresses cannot be relied on for contacting the owner.
86	     */
87	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
88	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
