93	    /** Request header carrying the client-supplied idempotency key for owner creation. */
94	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
95	
96	    /**
97	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that create originally
98	     * produced for it. A repeated create carrying a key found here returns that same owner instead of
99	     * creating a duplicate, making owner creation idempotent with respect to the key.
100	     */
101	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
