149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
152	        String idempotencyKey = currentIdempotencyKey();
153	        if (idempotencyKey != null) {
154	            Integer existingId = this.ownersByIdempotencyKey.get(idempotencyKey);
155	            if (existingId != null) {
156	                Owner existing = this.clinicService.findOwnerById(existingId);
157	                if (existing != null) {
158	                    return new ResponseEntity<>(toOwnerDtoWithBulkWarning(existing), HttpStatus.OK);
159	                }
160	            }
161	        }
162	        List<String> missingFields = new ArrayList<>();
163	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
164	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
165	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
166	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
167	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
168	        boolean hasStructuredAddress = !normalizedAddressLine1.isEmpty();
169	        String normalizedAddress = hasStructuredAddress
170	            ? composeAddress(normalizedAddressLine1, normalizedAddressLine2)
171	            : normalizedFlatAddress;
172	        requireNonBlank(missingFields, "address", normalizedAddress);
173	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
174	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
175	        if (!missingFields.isEmpty()) {
176	            throw new MissingRequiredFieldsException(missingFields);
177	        }
178	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
179	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
180	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
181	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
182	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
183	        requireDailyLimitNotReached(registrationDate);
184	        requireCityBelowCapacity(ownerFieldsDto.getCity());
185	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
186	        ownerFieldsDto.setTelephone(normalizedTelephone);
187	        if (ownerFieldsDto.getEmail() != null) {
188	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
189	        }
190	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
191	        HttpHeaders headers = new HttpHeaders();
192	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
193	        owner.setAddress(normalizedAddress);
194	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
195	        owner.setAddressLine2(hasStructuredAddress && !normalizedAddressLine2.isEmpty()
196	            ? normalizedAddressLine2 : null);
197	        owner.setRegistrationDate(registrationDate);
198	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
199	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
200	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
201	        requireUniqueIdentity(owner);
202	        markPossibleDuplicate(owner, sharesHousehold);
203	        this.clinicService.saveOwner(owner);
204	        if (idempotencyKey != null) {
205	            this.ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
206	        }
207	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
208	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
209	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
210	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
211	        headers.setLocation(UriComponentsBuilder.newInstance()
212	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
213	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
214	    }
