402	    /**
403	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
404	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
405	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
406	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
407	     * {@code "+61412345678"}.
408	     *
409	     * @param telephone the raw telephone value from the request
410	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
411	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
412	     */
413	    private static String normalizeTelephone(String telephone) {
414	        String e164 = toE164(telephone);
415	        if (e164 == null) {
416	            throw new InvalidFieldValueException("telephone",
417	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
418	        }
419	        return e164;
420	    }
