465	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
466	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
467	     *
468	     * @param email the raw email value from the request (already known to be non-null)
469	     * @return the lower-cased email to be stored and returned
470	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
471	     */
472	    private static String normalizeEmail(String email) {
473	        String trimmed = email.trim();
474	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
475	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
476	        }
