531	    /**
532	     * Caps the owner's {@code membershipLevel} so it cannot exceed one above the current maximum
533	     * membership level among the other members of its household (existing owners carrying the same
534	     * {@code householdId}, excluding the owner itself and any soft-deleted owner). When the household
535	     * has no other member — including when the owner has no {@code householdId} — no cap applies and
536	     * {@code level} is returned unchanged. Each household member's level is its own base level (points
537	     * mapped to a level for its real household size), so the cap does not depend on other capped
538	     * values.
539	     *
540	     * @param owner the owner whose membership level is being computed
541	     * @param level the owner's uncapped membership level derived from its membership points
542	     * @return the membership level capped at {@code maxHouseholdMemberLevel + 1}, or {@code level}
543	     *         when the owner has no other household member
544	     */
545	    private int capMembershipLevel(Owner owner, int level) {
546	        String householdId = owner.getHouseholdId();
547	        if (householdId == null) {
548	            return level;
549	        }
550	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
551	            .filter(existing -> !isDeleted(existing))
552	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
553	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
554	            .map(this::membershipLevelForOwner)
555	            .max(Integer::compareTo)
556	            .orElse(null);
557	        if (maxMemberLevel == null) {
558	            return level;
559	        }
560	        return Math.min(level, maxMemberLevel + 1);
561	    }
