615	    /**
616	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
617	     * forward, just like a weekend, until it reaches a non-holiday business day.
618	     */
619	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
620	        LocalDate.of(2026, 1, 1),
621	        LocalDate.of(2026, 1, 26),
622	        LocalDate.of(2026, 4, 25),
623	        LocalDate.of(2026, 12, 25),
624	        LocalDate.of(2026, 12, 28));
