626	    /**
627	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
628	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
629	     * the effective registration date (whether supplied in the request or defaulted to the server date)
630	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
631	     * from the registration date uses the adjusted date.
632	     *
633	     * @param date the effective registration date (supplied or defaulted), never {@code null}
634	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
635	     */
636	    private static LocalDate toBusinessDay(LocalDate date) {
637	        LocalDate adjusted = date;
638	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
639	            adjusted = adjusted.plusDays(1);
640	        }
641	        return adjusted;
642	    }
