644	    /** Whether {@code date} falls on a Saturday or Sunday. */
645	    private static boolean isWeekend(LocalDate date) {
646	        DayOfWeek day = date.getDayOfWeek();
647	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
648	    }
