653	    /**
654	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
655	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
656	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
657	     * present here and accepts any well-formed postcode.
658	     */
659	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
660	        "NSW", new int[] {2000, 2099},
661	        "VIC", new int[] {3000, 3099},
662	        "QLD", new int[] {4000, 4099});
