664	    /**
665	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
666	     * optional, so the request contract stays backward-compatible). When present it must be exactly
667	     * four digits and, for a city whose region is known, fall within that region's inclusive range
668	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
669	     * postcode. A malformed or out-of-range value is rejected with a 400.
670	     *
671	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
672	     * @param city the owner's city, used to look up the region whose range constrains the postcode
673	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
674	     */
675	    private void validatePostcode(String postcode, String city) {
676	        if (postcode == null) {
677	            return;
678	        }
679	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
680	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
681	        }
682	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
683	        int[] range = REGION_POSTCODES.get(region);
684	        if (range == null) {
685	            return;
686	        }
687	        int value = Integer.parseInt(postcode);
688	        if (value < range[0] || value > range[1]) {
689	            throw new InvalidFieldValueException("postcode",
690	                "Postcode must be valid for the city's region " + region);
691	        }
692	    }
