753	    /**
754	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate identity
755	     * check has passed, so the owner is known not to be a rejected duplicate. When an existing owner
756	     * has the same {@code soundex(lastName)} and the same {@code postcode} as this owner but a
757	     * <em>different</em> {@code identityKey}, the owner is a possible duplicate: {@code possibleDuplicate}
758	     * is set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
759	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
760	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
761	     * duplicate. An owner with no {@code postcode} never matches, since the soft match is keyed on it.
762	     *
763	     * @param owner the incoming owner, with its telephone, email and postcode populated
764	     * @param sharesHousehold whether the request opted in as a declared household member
765	     */
766	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
767	        owner.setPossibleDuplicate(false);
768	        owner.setPossibleDuplicateOf(null);
769	        if (sharesHousehold) {
770	            return;
771	        }
772	        String postcode = owner.getPostcode();
773	        if (postcode == null || postcode.isBlank()) {
774	            return;
775	        }
776	        String soundex = OwnerIdentity.soundex(owner.getLastName());
777	        String identityKey = ownerMapper.toIdentityKey(owner);
778	        this.clinicService.findAllOwners().stream()
779	            .filter(existing -> !isDeleted(existing))
780	            .filter(existing -> postcode.equals(existing.getPostcode()))
781	            .filter(existing -> soundex.equals(OwnerIdentity.soundex(existing.getLastName())))
782	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
783	            .min(java.util.Comparator.comparing(Owner::getId))
784	            .ifPresent(match -> {
785	                owner.setPossibleDuplicate(true);
786	                owner.setPossibleDuplicateOf(match.getId());
787	            });
