799	    /**
800	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
801	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
802	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
803	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
804	     * value normalizes to the empty string, so the required-field check rejects an address that is
805	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
806	     *
807	     * @param address the raw address value from the request (may be {@code null})
808	     * @return the normalized address, or the empty string when blank after normalization
809	     */
810	    private static String normalizeAddress(String address) {
811	        if (address == null) {
812	            return "";
813	        }
814	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
815	        if (collapsed.isEmpty()) {
816	            return "";
817	        }
818	        String[] tokens = collapsed.split(" ");
819	        StringBuilder sb = new StringBuilder();
820	        for (String token : tokens) {
821	            String expanded = switch (token) {
822	                case "ST" -> "STREET";
823	                case "RD" -> "ROAD";
824	                case "AVE" -> "AVENUE";
825	                default -> token;
826	            };
827	            if (sb.length() > 0) {
828	                sb.append(' ');
829	            }
830	            sb.append(expanded);
831	        }
832	        return sb.toString();
833	    }
