854	     * upper-cased first 12 hex characters of the SHA-256 digest of
855	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
856	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
857	     * identifier is a deterministic function of the normalized last name and postcode, owners that
858	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
859	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
860	     * postcode and there is then nothing to key on.
861	     *
862	     * @param lastName the owner's last name (already validated non-blank)
863	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
864	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
865	     */
866	    private static String householdIdFor(String lastName, String postcode) {
867	        if (postcode == null || postcode.isBlank()) {
868	            return null;
869	        }
870	        String normalizedLastName = normalizeForHousehold(lastName);
871	        try {
872	            byte[] digest = MessageDigest.getInstance("SHA-256")
873	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
874	            StringBuilder sb = new StringBuilder();
875	            for (byte b : digest) {
876	                sb.append(String.format("%02X", b));
877	            }
878	            return sb.substring(0, 12);
879	        }
880	        catch (NoSuchAlgorithmException e) {
881	            throw new IllegalStateException("SHA-256 not available", e);
882	        }
883	    }
884	}
