88	        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
89	        String soundex = OwnerIdentity.soundex(owner.getLastName());
90	        return OwnerIdentity.sha256Hex(telephone + "|" + email + "|" + soundex);
91	    }
92	
93	    /**
94	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
95	     * email, otherwise {@code 'PHONE'}.
96	     */
97	    @Named("toContactPreference")
98	    default String toContactPreference(Owner owner) {
99	        if (owner == null) {
100	            return null;
101	        }
102	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
103	        return hasEmail ? "EMAIL" : "PHONE";
104	    }
105	
106	    /**
107	     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
108	     */
109	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
110	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
111	
112	    /**
113	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name
114	     * ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}).
115	     */
116	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
117	        "NSW", "Australia/Sydney",
118	        "VIC", "Australia/Melbourne",
119	        "QLD", "Australia/Brisbane");
120	
121	    /**
122	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
123	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
124	     * owner's locality from its postcode in preference to its city.
125	     */
126	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
127	        "NSW", new int[] {2000, 2099},
128	        "VIC", new int[] {3000, 3099},
129	        "QLD", new int[] {4000, 4099});
130	
131	    /**
132	     * Derives the owner's canonical region, the {@code REGION} component of its {@code customerCode}.
133	     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
134	     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
135	     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
136	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
137	     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
138	     * the same region for known cities but disambiguates cities that share a name.
139	     */
140	    default String toRegion(Owner owner) {
141	        if (owner == null) {
142	            return null;
143	        }
144	        String regionByPostcode = regionForPostcode(owner.getPostcode());
145	        if (regionByPostcode != null) {
146	            return regionByPostcode;
147	        }
148	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
149	    }
