173	    /**
174	     * Derives the owner's {@code timezone} as the IANA timezone name mapped from its locality/region
175	     * via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
176	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Returns {@code null} when the
177	     * owner's region is not one of the tabled regions.
178	     */
