187	    /**
188	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
189	     * {@code null} when the postcode is absent, malformed, or in no known range.
190	     */
191	    private static String regionForPostcode(String postcode) {
192	        if (postcode == null || !postcode.matches("\\d{4}")) {
193	            return null;
194	        }
195	        int value = Integer.parseInt(postcode);
196	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
197	            int[] range = entry.getValue();
198	            if (value >= range[0] && value <= range[1]) {
199	                return entry.getKey();
200	            }
201	        }
202	        return null;
203	    }
