233	    /**
234	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
235	     * the national digits grouped in threes, e.g. {@code "+61412345678"} becomes
236	     * {@code "+61 412 345 678"}. The country code is a single {@code '1'} for NANP ({@code +1}) numbers
237	     * and two digits otherwise (covering the {@code +61} numbers the app stores). Returns the value
238	     * unchanged when it is absent or not a well-formed E.164 number, leaving raw {@code telephone}
239	     * untouched.
240	     */
241	    @Named("toTelephoneDisplay")
242	    default String toTelephoneDisplay(Owner owner) {
243	        if (owner == null) {
244	            return null;
245	        }
246	        String telephone = owner.getTelephone();
247	        if (telephone == null || !telephone.matches("\\+[0-9]{8,15}")) {
248	            return telephone;
249	        }
250	        String digits = telephone.substring(1);
251	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
252	        String countryCode = digits.substring(0, countryCodeLength);
253	        String national = digits.substring(countryCodeLength);
254	        StringBuilder sb = new StringBuilder("+").append(countryCode);
255	        for (int i = 0; i < national.length(); i++) {
256	            if (i % 3 == 0) {
257	                sb.append(' ');
258	            }
259	            sb.append(national.charAt(i));
260	        }
261	        return sb.toString();
262	    }
