307	    /**
308	     * Returns the fiscal year of the given date as the calendar year in which the fiscal year ends.
309	     * The fiscal year starts on 1 July, so a date in July or later belongs to the fiscal year ending
310	     * in the next calendar year ({@code year + 1}); an earlier date belongs to the fiscal year ending
311	     * in its own calendar year.
312	     *
313	     * @param date the date whose fiscal year is computed, never {@code null}
314	     * @return the calendar year in which the date's fiscal year ends
315	     */
316	    static int fiscalYear(LocalDate date) {
317	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
318	    }
319	
320	    /**
321	     * Returns the owner's membership points, assigned on creation: starts at {@code 0}, plus {@code 2}
322	     * when a non-blank email is present, plus {@code 1} when the owner has no namesakes
323	     * ({@code namesakeCount} is 0), plus {@code 2} for a household of {@code 3} or more members, plus
324	     * {@code 3} for a tenure of one or more elapsed fiscal years since the {@code registrationDate}.
325	     * This qualified mapping cannot observe the owner's household size (which requires counting other
326	     * owners), so it computes the points as if the owner were the only member of its household; the
327	     * controller recomputes the points with the real household size via
328	     * {@link #membershipPointsFor(Owner, int)} before returning the owner.
329	     */
330	    @Named("toMembershipPoints")
331	    default Integer toMembershipPoints(Owner owner) {
332	        if (owner == null) {
333	            return null;
334	        }
335	        return membershipPointsFor(owner, 1);
336	    }
337	
338	    /**
339	     * Returns the owner's numeric membership level, derived from its membership points: level
340	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
341	     * {@code 4} for {@code 6} or more. As with {@link #toMembershipPoints(Owner)}, the household size
342	     * is not observable here and is treated as a single member.
343	     */
344	    @Named("toMembershipLevel")
345	    default Integer toMembershipLevel(Owner owner) {
346	        if (owner == null) {
347	            return null;
348	        }
349	        return membershipLevelFor(membershipPointsFor(owner, 1));
350	    }
351	
352	    /**
353	     * Computes an owner's membership points from the given household size: starts at {@code 0}, plus
354	     * {@code 2} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
355	     * ({@code namesakeCount} is 0), plus {@code 2} when {@code householdSize} is {@code 3} or more,
356	     * plus {@code 3} for a tenure of one or more elapsed fiscal years (each starting 1 July) between
357	     * the {@code registrationDate} and today.
358	     *
359	     * @param owner the owner whose points are computed, never {@code null}
360	     * @param householdSize the number of owners sharing the owner's household
361	     * @return the owner's membership points
362	     */
363	    static int membershipPointsFor(Owner owner, int householdSize) {
364	        int points = 0;
365	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
366	        if (hasEmail) {
367	            points += 2;
368	        }
369	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
370	        if (noNamesakes) {
371	            points += 1;
372	        }
373	        if (householdSize >= 3) {
374	            points += 2;
375	        }
376	        boolean tenured = owner.getRegistrationDate() != null
377	            && fiscalYear(LocalDate.now()) - fiscalYear(owner.getRegistrationDate()) >= 1;
378	        if (tenured) {
379	            points += 3;
380	        }
381	        return points;
382	    }
383	
384	    /**
385	     * Maps membership points to the numeric membership level: level {@code 1} for {@code 0-1} points,
386	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
387	     *
388	     * @param points the owner's membership points
389	     * @return the corresponding membership level (1-4)
390	     */
391	    static int membershipLevelFor(int points) {
392	        if (points <= 1) {
393	            return 1;
394	        }
395	        if (points <= 3) {
396	            return 2;
397	        }
398	        if (points <= 5) {
399	            return 3;
400	        }
401	        return 4;
402	    }
403	
404	    /**
405	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
406	     * contained in the owner's {@code customerCode}. Returns {@code null} when the customer code is
407	     * absent.
408	     */
409	    @Named("toCheckDigit")
410	    default Integer toCheckDigit(Owner owner) {
411	        if (owner == null || owner.getCustomerCode() == null) {
412	            return null;
413	        }
414	        int sum = 0;
415	        boolean dbl = true;
416	        String code = owner.getCustomerCode();
417	        for (int i = code.length() - 1; i >= 0; i--) {
418	            char c = code.charAt(i);
419	            if (c < '0' || c > '9') {
420	                continue;
421	            }
422	            int d = c - '0';
423	            if (dbl) {
424	                d *= 2;
425	                if (d > 9) {
426	                    d -= 9;
427	                }
428	            }
429	            sum += d;
430	            dbl = !dbl;
431	        }
432	        return (10 - (sum % 10)) % 10;
433	    }
